    41→#[derive(Parser)]
    42→#[command(name = "pr-builds")]
    43→#[command(about = "Manage PR builds for Spice.ai", long_about = None)]
    44→struct Cli {
    45→    #[command(subcommand)]
    46→    command: Commands,
    47→}
    48→
    49→#[derive(Subcommand)]
    50→enum Commands {
    51→    /// Trigger a build for the current (or specified) branch.
    52→    ///
    53→    /// Triggers the '`build_and_release`' workflow in GitHub Actions.
    54→    /// If an active build exists for the latest commit (SHA-based), it will be reused.
    55→    /// If a successful build exists (for this commit), no action is taken.
    56→    Trigger {
    57→        /// Branch to trigger build for. Defaults to current branch.
    58→        #[arg(short, long)]
    59→        branch: Option<String>,
    60→
    61→        /// PR number to resolve to a branch.
    62→        #[arg(short, long)]
    63→        pr: Option<u64>,
    64→
    65→        /// Build tag to trigger (all, default, odbc, metal). Defaults to all.
    66→        #[arg(short, long)]
    67→        tag: Option<TagOption>,
    68→
    69→        /// Wait for the build to complete.
    70→        ///
    71→        /// If an existing build is reused, this will wait for that build.
    72→        #[arg(short, long)]
    73→        wait: bool,
    74→    },
    75→    /// Install the latest binary for the current (or specified) branch.
    76→    ///
    77→    /// Downloads and installs the 'spiced' binary from the latest successful
    78→    /// GitHub Actions run for the branch.
    79→    Install {
    80→        /// Branch to install binary for. Defaults to current branch.
    81→        #[arg(short, long)]
    82→        branch: Option<String>,
    83→
    84→        /// PR number to resolve to a branch.
    85→        #[arg(short, long)]
    86→        pr: Option<u64>,
    87→    },
    88→    /// Run the binary for the current (or specified) branch.
    89→    ///
    90→    /// If the binary is not installed locally, it will be automatically downloaded
    91→    /// and installed from the latest successful build.
    92→    Run {
    93→        /// Branch to run binary for. Defaults to current branch.
    94→        #[arg(short, long)]
    95→        branch: Option<String>,
    96→
    97→        /// PR number to resolve to a branch.
    98→        #[arg(short, long)]
    99→        pr: Option<u64>,
   100→
   101→        /// Interactive mode: select a branch from installed binaries
   102→        #[arg(short, long)]
   103→        interactive: bool,
   104→
   105→        /// Arguments to pass to spiced
   106→        #[arg(last = true)]
   107→        args: Vec<String>,
   108→    },
   109→}
   110→
   111→#[derive(Deserialize, Debug)]
   112→struct GhRun {
   113→    #[serde(rename = "databaseId")]
   114→    database_id: u64,
   115→}
   116→
   117→#[derive(Deserialize, Debug)]
   118→struct GhPr {
   119→    #[serde(rename = "headRefName")]
   120→    head_ref_name: String,
   121→}
   122→
   123→#[derive(Deserialize)]
   124→struct GhRepo {
   125→    #[serde(rename = "nameWithOwner")]
   126→    name_with_owner: String,
   127→}
   128→
   129→#[cfg(unix)]
   130→fn main() -> Result<()> {
   131→    let cli = Cli::parse();
   132→
   133→    match &cli.command {
   134→        Commands::Trigger {
   135→            branch,
   136→            pr,
   137→            tag,
   138→            wait,
   139→        } => trigger_build(branch.as_deref(), *pr, *tag, *wait),
   140→        Commands::Install { branch, pr } => install_build(branch.as_deref(), *pr),
   141→        Commands::Run {
   142→            branch,
   143→            pr,
   144→            interactive,
   145→            args,
   146→        } => run_build(branch.as_deref(), *pr, *interactive, args),
   147→    }
   148→}
   149→
   150→#[cfg(not(unix))]
   151→fn main() -> Result<()> {
   152→    anyhow::bail!("This tool is currently only supported on Unix-like systems.");
   153→}
