   155→#[cfg(unix)]
   156→fn resolve_branch_or_pr(branch: Option<&str>, pr: Option<u64>) -> Result<String> {
   157→    if let Some(b) = branch {
   158→        return Ok(b.to_string());
   159→    }
   160→
   161→    if let Some(pr_num) = pr {
   162→        println!("Resolving PR #{pr_num} to branch...");
   163→        let output = Command::new("gh")
   164→            .args(["pr", "view", &pr_num.to_string(), "--json", "headRefName"])
   165→            .output()
   166→            .context("Failed to execute gh pr view")?;
   167→
   168→        if !output.status.success() {
   169→            anyhow::bail!(
   170→                "Failed to resolve PR #{}: {}",
   171→                pr_num,
   172→                String::from_utf8_lossy(&output.stderr)
   173→            );
   174→        }
   175→
   176→        let pr_data: GhPr = serde_json::from_slice(&output.stdout)?;
   177→        println!(
   178→            "Resolved PR #{} to branch '{}'",
   179→            pr_num, pr_data.head_ref_name
   180→        );
   181→        return Ok(pr_data.head_ref_name);
   182→    }
   183→
   184→    get_current_branch()
   185→}
   186→
   187→#[cfg(unix)]
   188→fn get_current_branch() -> Result<String> {
   189→    let output = Command::new("git")
   190→        .args(["branch", "--show-current"])
   191→        .output()
   192→        .context("Failed to execute git command")?;
   193→
   194→    if !output.status.success() {
   195→        anyhow::bail!("git branch --show-current failed");
   196→    }
   197→
   198→    let branch = String::from_utf8(output.stdout)
   199→        .context("Branch name is not valid UTF-8")?
   200→        .trim()
   201→        .to_string();
   202→
   203→    if branch.is_empty() {
   204→        anyhow::bail!("Could not determine current branch");
   205→    }
   206→    Ok(branch)
   207→}
   208→
   209→fn validate_branch_name(branch: &str) -> Result<()> {
   210→    if branch.is_empty() {
   211→        anyhow::bail!("Branch name cannot be empty");
   212→    }
   213→    if branch.contains("..") {
   214→        anyhow::bail!("Branch name cannot contain '..'");
   215→    }
   216→    if branch.starts_with('/') || branch.contains(':') {
   217→        anyhow::bail!("Branch name contains invalid characters");
   218→    }
   219→    Ok(())
   220→}
   221→
   222→#[cfg(unix)]
   223→fn get_repo_owner_name() -> Result<String> {
   224→    let output = Command::new("gh")
   225→        .args(["repo", "view", "--json", "nameWithOwner"])
   226→        .output()
   227→        .context("Failed to determine current repository via gh repo view")?;
   228→
   229→    if !output.status.success() {
   230→        anyhow::bail!(
   231→            "gh repo view failed: {}",
   232→            String::from_utf8_lossy(&output.stderr)
   233→        );
   234→    }
   235→
   236→    let gh_repo: GhRepo =
   237→        serde_json::from_slice(&output.stdout).context("Failed to parse gh repo view output")?;
   238→    Ok(gh_repo.name_with_owner)
   239→}
   240→
   241→#[cfg(unix)]
   242→fn trigger_build(
   243→    branch: Option<&str>,
   244→    pr: Option<u64>,
   245→    tag: Option<TagOption>,
   246→    wait: bool,
   247→) -> Result<()> {
   248→    let branch = resolve_branch_or_pr(branch, pr)?;
   249→    validate_branch_name(&branch)?;
   250→    let repo_owner_name = get_repo_owner_name()?;
   251→
   252→    // Get the latest commit SHA for the branch
   253→    println!("Fetching latest commit SHA for branch '{branch}'...");
   254→    let output = Command::new("gh")
   255→        .args([
   256→            "api",
   257→            &format!("repos/{repo_owner_name}/branches/{branch}"),
   258→            "--jq",
   259→            ".commit.sha",
   260→        ])
   261→        .output()
   262→        .context("Failed to fetch branch SHA")?;
   263→
   264→    if !output.status.success() {
   265→        anyhow::bail!(
   266→            "Failed to get branch SHA: {}",
   267→            String::from_utf8_lossy(&output.stderr)
   268→        );
   269→    }
   270→
   271→    let latest_sha = String::from_utf8(output.stdout)?.trim().to_string();
   272→    println!("Latest SHA: {latest_sha}");
   273→
   274→    // Check for existing runs for this SHA
   275→    println!("Checking for existing builds for this SHA...");
   276→    let output = Command::new("gh")
   277→        .args([
   278→            "run",
   279→            "list",
   280→            "--workflow",
   281→            "build_and_release.yml",
   282→            "--branch",
   283→            &branch,
   284→            "--limit",
   285→            "5", // Check a few recent runs
   286→            "--json",
   287→            "databaseId,headSha,status,conclusion",
   288→        ])
   289→        .output()
   290→        .context("Failed to list recent runs")?;
   291→
   292→    let mut existing_run_id: Option<u64> = None;
   293→    let mut max_seen_id: u64 = 0;
   294→
   295→    if output.status.success() {
   296→        let runs: Vec<serde_json::Value> = serde_json::from_slice(&output.stdout)?;
   297→        for run in runs {
   298→            if let Some(id) = run["databaseId"].as_u64()
   299→                && id > max_seen_id
   300→            {
   301→                max_seen_id = id;
   302→            }
   303→
   304→            if let Some(run_sha) = run["headSha"].as_str()
   305→                && run_sha == latest_sha
   306→            {
   307→                // Found a run for the same SHA
   308→                let status = run["status"].as_str().unwrap_or("");
   309→                let conclusion = run["conclusion"].as_str().unwrap_or("");
   310→                let id = run["databaseId"].as_u64();
   311→
   312→                if let Some(id) = id {
   313→                    if status == "completed" && conclusion == "success" {
   314→                        println!(
   315→                            "Found successful build for this SHA (Run ID: {id}). No need to trigger.",
   316→                        );
   317→                        return Ok(());
   318→                    } else if status != "completed" {
   319→                        println!("Found active build for this SHA (Run ID: {id}). Reusing it.",);
   320→                        existing_run_id = Some(id);
   321→                        break;
   322→                    }
   323→
   324→                    println!(
   325→                        "Found failed/cancelled build for this SHA (Run ID: {id}). Retrying...",
   326→                    );
   327→                    // If failed, we probably want to trigger a new one, so continue loop or stop?
   328→                    // Default behavior: trigger new if latest is failed.
   329→                }
   330→            }
   331→        }
   332→    }
   333→
   334→    let run_id_to_watch = if let Some(id) = existing_run_id {
   335→        id
   336→    } else {
   337→        println!("No active build found for latest SHA. Triggering new build...");
   338→
   339→        let platform_option = {
   340→            let os = env::consts::OS;
   341→            let arch = env::consts::ARCH;
   342→            match (os, arch) {
   343→                ("linux", "aarch64") => "Linux aarch64".to_string(),
   344→                ("linux", "x86_64") => "Linux x64".to_string(),
   345→                ("macos", "aarch64") => "macOS aarch64 (Apple Silicon)".to_string(),
   346→                ("macos", "x86_64") => {
   347→                    anyhow::bail!(
   348→                        "Failed to determine build platform for OS macOS and architecture x86_64: Intel macOS is not supported by the build_and_release workflow. Use an Apple Silicon macOS or supported Linux machine to trigger this build."
   349→                    );
   350→                }
   351→                (other_os, other_arch) => {
   352→                    anyhow::bail!(
   353→                        "Failed to determine build platform for OS {other_os} and architecture {other_arch}: Unsupported combination for build_and_release workflow. Supported combinations are: linux/aarch64, linux/x86_64, macos/aarch64.",
   354→                    );
   355→                }
   356→            }
   357→        };
   358→
   359→        println!("Requesting platform: {platform_option}");
   360→
   361→        let mut cmd_args: Vec<String> = vec![
   362→            "workflow".to_string(),
   363→            "run".to_string(),
   364→            "build_and_release.yml".to_string(),
   365→            "--ref".to_string(),
   366→            branch.clone(),
   367→            "-f".to_string(),
   368→            format!("platform_option={platform_option}"),
   369→        ];
   370→
   371→        if let Some(t) = tag {
   372→            let tag_option = format!(
   373→                "tag_option={}",
   374→                match t {
   375→                    TagOption::All => "all",
   376→                    TagOption::Default => "default",
   377→                    TagOption::Odbc => "odbc",
   378→                    TagOption::Metal => "metal",
   379→                }
   380→            );
   381→            println!("Requesting {tag_option}");
   382→            cmd_args.push("-f".to_string());
   383→
   384→            cmd_args.push(tag_option);
   385→        }
   386→
   387→        let status = Command::new("gh")
   388→            .args(&cmd_args)
   389→            .status()
   390→            .context("Failed to execute gh workflow run")?;
   391→
   392→        if !status.success() {
   393→            anyhow::bail!("Failed to trigger build");
   394→        }
   395→
   396→        println!("Build triggered successfully.");
   397→
   398→        if !wait {
   399→            println!("You can check the status with:");
   400→            println!("  gh run list --workflow build_and_release.yml --branch \"{branch}\"",);
   401→            return Ok(());
   402→        }
   403→
   404→        println!("Waiting for build to start...");
   405→
   406→        let mut found_new_run_id: Option<u64> = None;
   407→
   408→        // Poll for up to 30 seconds to find the new run
   409→        for _ in 0..10 {
   410→            std::thread::sleep(std::time::Duration::from_secs(3));
   411→
   412→            let output = Command::new("gh")
   413→                .args([
   414→                    "run",
   415→                    "list",
   416→                    "--workflow",
   417→                    "build_and_release.yml",
   418→                    "--branch",
   419→                    &branch,
   420→                    "--limit",
   421→                    "1",
   422→                    "--json",
   423→                    "databaseId,status,createdAt,headSha",
   424→                ])
   425→                .output()
   426→                .context("Failed to fetch latest run ID")?;
   427→
   428→            if output.status.success() {
   429→                let runs: Vec<serde_json::Value> = serde_json::from_slice(&output.stdout)?;
   430→                if let Some(run) = runs.first() {
   431→                    let status = run["status"].as_str().unwrap_or("");
   432→                    let run_sha = run["headSha"].as_str().unwrap_or("");
   433→                    let id = run["databaseId"].as_u64();
   434→
   435→                    // Ensure we picked up a run for the correct SHA that is active and NEW (id > max_seen_id)
   436→                    if let Some(id) = id
   437→                        && id > max_seen_id
   438→                        && (status == "queued"
   439→                            || status == "in_progress"
   440→                            || status == "requested"
   441→                            || status == "waiting")
   442→                        && run_sha == latest_sha
   443→                    {
   444→                        found_new_run_id = Some(id);
   445→                        break;
   446→                    }
   447→                }
   448→            }
   449→        }
   450→
   451→        found_new_run_id
   452→            .context("Could not find the newly triggered run (or it completed instantly).")?
   453→    };
   454→
   455→    if wait {
   456→        println!("Waiting for Run ID: {run_id_to_watch}...");
   457→        let status = Command::new("gh")
   458→            .args(["run", "watch", &run_id_to_watch.to_string()])
   459→            .status()
   460→            .context("Failed to watch run")?;
   461→
   462→        if status.success() {
   463→            println!("Build completed successfully!");
   464→        } else {
   465→            anyhow::bail!("Build failed or was cancelled.");
   466→        }
   467→    }
   468→
   469→    Ok(())
   470→}
   471→
   472→fn get_artifact_names() -> Result<Vec<String>> {
   473→    let (os, arch) = match env::consts::OS {
   474→        // CI only builds aarch64 for macOS (Apple Silicon)
   475→        "macos" => ("darwin", "aarch64"),
   476→        // For Linux, the CI uses standard architecture names (x86_64, aarch64)
   477→        "linux" => ("linux", env::consts::ARCH),
   478→        // Fallback/Default
   479→        other => {
   480→            anyhow::bail!(
   481→                "Unsupported OS '{other}' for PR build artifacts; only 'macos' and 'linux' are supported",
   482→            );
   483→        }
   484→    };
   485→
   486→    // Prioritize metal for darwin
   487→    let mut names = Vec::new();
   488→    if os == "darwin" {
   489→        names.push(format!("spiced_metal_{os}_{arch}"));
   490→    }
   491→    names.push(format!("spiced_{os}_{arch}"));
   492→
   493→    Ok(names)
   494→}
   495→
   496→#[derive(Deserialize, Debug)]
   497→struct Artifact {
   498→    name: String,
   499→}
   500→
   501→#[derive(Deserialize, Debug)]
   502→struct ArtifactList {
   503→    artifacts: Vec<Artifact>,
   504→}
   505→
   506→#[cfg(unix)]
   507→fn install_build(branch: Option<&str>, pr: Option<u64>) -> Result<()> {
   508→    let branch = resolve_branch_or_pr(branch, pr)?;
   509→    validate_branch_name(&branch)?;
   510→    let repo_owner_name = get_repo_owner_name()?;
   511→
   512→    let target_dir = dirs::home_dir()
   513→        .context("Could not find home directory")?
   514→        .join(".spice/bin")
   515→        .join(&branch);
   516→
   517→    println!("Looking for latest successful build for branch: {branch}...",);
   518→
   519→    let output = Command::new("gh")
   520→        .args([
   521→            "run",
   522→            "list",
   523→            "--workflow",
   524→            "build_and_release.yml",
   525→            "--branch",
   526→            &branch,
   527→            "--status",
   528→            "success",
   529→            "--limit",
   530→            "1",
   531→            "--json",
   532→            "databaseId",
   533→        ])
   534→        .output()
   535→        .context("Failed to execute gh run list")?;
   536→
   537→    if !output.status.success() {
   538→        anyhow::bail!(
   539→            "gh run list failed: {}",
   540→            String::from_utf8_lossy(&output.stderr)
   541→        );
   542→    }
   543→
   544→    let runs: Vec<GhRun> = serde_json::from_slice(&output.stdout)?;
   545→    let run = runs
   546→        .first()
   547→        .context(format!("No successful build found for branch '{branch}'"))?;
   548→    let run_id = run.database_id;
   549→
   550→    println!("Found Run ID: {run_id}");
   551→
   552→    // List artifacts for the run to check which one exists
   553→    println!("Checking available artifacts...");
   554→    let output = Command::new("gh")
   555→        .args([
   556→            "api",
   557→            &format!("repos/{repo_owner_name}/actions/runs/{run_id}/artifacts",),
   558→        ])
   559→        .output()
   560→        .context("Failed to fetch artifacts list")?;
   561→
   562→    if !output.status.success() {
   563→        anyhow::bail!(
   564→            "Failed to list artifacts: {}",
   565→            String::from_utf8_lossy(&output.stderr)
   566→        );
   567→    }
   568→
   569→    let artifact_list: ArtifactList = serde_json::from_slice(&output.stdout)?;
   570→    let available_artifacts: Vec<String> = artifact_list
   571→        .artifacts
   572→        .into_iter()
   573→        .map(|a| a.name)
   574→        .collect();
   575→
   576→    let wanted_artifacts = get_artifact_names()?;
   577→    let artifact_to_download = wanted_artifacts
   578→        .iter()
   579→        .find(|name| available_artifacts.contains(name))
   580→        .context("No compatible artifact found in this build")?;
   581→
   582→    let temp_dir = tempfile::tempdir()?;
   583→    let temp_path = temp_dir.path();
   584→
   585→    println!(
   586→        "Downloading artifact '{}' to {}...",
   587→        artifact_to_download,
   588→        temp_path.display()
   589→    );
   590→
   591→    let status = Command::new("gh")
   592→        .args([
   593→            "run",
   594→            "download",
   595→            &run_id.to_string(),
   596→            "-n",
   597→            artifact_to_download,
   598→            "-D",
   599→        ])
   600→        .arg(temp_path)
   601→        .stdout(Stdio::null())
   602→        .stderr(Stdio::inherit())
   603→        .status()
   604→        .context("Failed to execute gh run download")?;
   605→
   606→    if !status.success() {
   607→        anyhow::bail!("Failed to download artifact");
   608→    }
   609→
   610→    println!("Installing to {}...", target_dir.display());
   611→    fs::create_dir_all(&target_dir)?;
   612→
   613→    // Find tar.gz
   614→    let mut tar_file: Option<PathBuf> = None;
   615→    for entry in fs::read_dir(temp_path)? {
   616→        let entry = entry?;
   617→        let path = entry.path();
   618→        if let Some(ext) = path.extension()
   619→            && ext == "gz"
   620→        {
   621→            tar_file = Some(path);
   622→            break;
   623→        }
   624→    }
   625→
   626→    let tar_file = tar_file.context("No tar.gz file found in downloaded artifact")?;
   627→
   628→    // Extract directly to target location
   629→    let tar_gz = fs::File::open(&tar_file)?;
   630→    let tar = GzDecoder::new(tar_gz);
   631→    let mut archive = Archive::new(tar);
   632→
   633→    // Use a temp file in the target directory for extraction
   634→    let temp_target = target_dir.join("spiced.tmp");
   635→    let mut found_binary = false;
   636→
   637→    for entry in archive.entries()? {
   638→        let mut entry = entry?;
   639→        let path = entry.path()?;
   640→        if path.ends_with("spiced") {
   641→            println!("Extracting binary to {}...", temp_target.display());
   642→            entry.unpack(&temp_target)?;
   643→            found_binary = true;
   644→            break;
   645→        }
   646→    }
   647→
   648→    if !found_binary {
   649→        anyhow::bail!("Could not find 'spiced' binary in archive");
   650→    }
   651→
   652→    let target_binary = target_dir.join("spiced");
   653→
   654→    // Make executable before rename
   655→    let mut perms = fs::metadata(&temp_target)?.permissions();
   656→    perms.set_mode(0o755);
   657→    fs::set_permissions(&temp_target, perms)?;
   658→
   659→    // Rename might fail if cross-device link (EXDEV), so we try copy+remove as fallback
   660→    if let Err(e) = fs::rename(&temp_target, &target_binary) {
   661→        if e.kind() == std::io::ErrorKind::CrossesDevices {
   662→            fs::copy(&temp_target, &target_binary)?;
   663→            let _ = fs::remove_file(&temp_target);
   664→        } else {
   665→            return Err(e.into());
   666→        }
   667→    }
   668→
   669→    println!("Installed spiced to {}", target_binary.display());
   670→
   671→    // Symlink
   672→    let symlink_path = dirs::home_dir()
   673→        .context("Could not find home directory")?
   674→        .join(".spice/bin/spiced-dev");
   675→
   676→    // Remove existing symlink if it exists
   677→    if symlink_path.exists() || fs::symlink_metadata(&symlink_path).is_ok() {
   678→        fs::remove_file(&symlink_path).ok();
   679→    }
   680→
   681→    std::os::unix::fs::symlink(&target_binary, &symlink_path)?;
   682→
   683→    println!(
   684→        "Updated symlink: {} -> {}",
   685→        symlink_path.display(),
   686→        target_binary.display()
   687→    );
   688→    println!(
   689→        "You can now run it comfortably via: {}",
   690→        symlink_path.display()
   691→    );
   692→
   693→    Ok(())
   694→}
   695→
   696→#[cfg(unix)]
   697→fn run_build(
   698→    branch: Option<&str>,
   699→    pr: Option<u64>,
   700→    interactive: bool,
   701→    args: &[String],
   702→) -> Result<()> {
   703→    let branch = if interactive {
   704→        select_branch()?
   705→    } else {
   706→        resolve_branch_or_pr(branch, pr)?
   707→    };
   708→    validate_branch_name(&branch)?;
   709→
   710→    let binary_path = dirs::home_dir()
   711→        .context("Could not find home directory")?
   712→        .join(".spice/bin")
   713→        .join(&branch)
   714→        .join("spiced");
   715→
   716→    if !binary_path.exists() {
   717→        println!(
   718→            "Binary not found at {}. Installing...",
   719→            binary_path.display()
   720→        );
   721→        install_build(Some(&branch), None)?;
   722→    }
   723→
   724→    println!("Running spiced from branch '{branch}'...");
   725→    println!("Exec: {} {}", binary_path.display(), args.join(" "));
   726→
   727→    // Replace the current process with spiced (Unix only)
   728→    let error = Command::new(&binary_path).args(args).exec();
   729→
   730→    // If we're here, exec failed
   731→    anyhow::bail!("Failed to execute spiced: {error}");
   732→}
   733→
   734→#[cfg(unix)]
   735→fn select_branch() -> Result<String> {
   736→    let base_dir = dirs::home_dir()
   737→        .context("Could not find home directory")?
   738→        .join(".spice/bin");
   739→
   740→    if !base_dir.exists() {
   741→        anyhow::bail!("No binaries found in {}", base_dir.display());
   742→    }
   743→
   744→    let mut branches = Vec::new();
   745→
   746→    // Walk directory to find all 'spiced' binaries
   747→    for entry in WalkDir::new(&base_dir).min_depth(1) {
   748→        let entry = entry.ok();
   749→        if let Some(entry) = entry
   750→            && entry.file_type().is_file()
   751→            && entry.file_name() == "spiced"
   752→        {
   753→            // Found a spiced binary, the parent dir is the branch path
   754→            if let Some(branch_dir) = entry.path().parent() {
   755→                // Get relative path from base_dir to get the branch name
   756→                if let Ok(rel_path) = branch_dir.strip_prefix(&base_dir)
   757→                    && let Some(branch_name) = rel_path.to_str()
   758→                    && !branch_name.is_empty()
   759→                {
   760→                    branches.push(branch_name.to_string());
   761→                }
   762→            }
   763→        }
   764→    }
   765→
   766→    if branches.is_empty() {
   767→        anyhow::bail!("No installed branches found in {}", base_dir.display());
   768→    }
   769→
   770→    branches.sort();
   771→
   772→    let selection = dialoguer::Select::new()
   773→        .with_prompt("Select a branch to run")
   774→        .items(&branches)
   775→        .default(0)
   776→        .interact()
   777→        .context("Failed to select branch")?;
   778→
   779→    Ok(branches[selection].clone())
   780→}
   781→

